create policy effects_public_select on public.effect_definitions for select to authenticated using (true);
create policy compendium_source_select on public.compendium_sources for select to authenticated using (campaign_id is null or exists (select 1 from public.campaign_members m where m.campaign_id = compendium_sources.campaign_id and m.user_id = auth.uid()) or exists (select 1 from public.campaigns c where c.id = compendium_sources.campaign_id and c.owner_id = auth.uid()));
create policy compendium_source_gm_write on public.compendium_sources for all to authenticated using (campaign_id is not null and (exists (select 1 from public.campaign_members m where m.campaign_id = compendium_sources.campaign_id and m.user_id = auth.uid() and m.role = 'gm'::campaign_role) or exists (select 1 from public.campaigns c where c.id = compendium_sources.campaign_id and c.owner_id = auth.uid()))) with check (campaign_id is not null and (exists (select 1 from public.campaign_members m where m.campaign_id = compendium_sources.campaign_id and m.user_id = auth.uid() and m.role = 'gm'::campaign_role) or exists (select 1 from public.campaigns c where c.id = compendium_sources.campaign_id and c.owner_id = auth.uid())));
create policy compendium_entry_select on public.compendium_entries for select to authenticated using (campaign_id is null or exists (select 1 from public.campaign_members m where m.campaign_id = compendium_entries.campaign_id and m.user_id = auth.uid()) or exists (select 1 from public.campaigns c where c.id = compendium_entries.campaign_id and c.owner_id = auth.uid()));
create policy compendium_entry_gm_write on public.compendium_entries for all to authenticated using (campaign_id is not null and (exists (select 1 from public.campaign_members m where m.campaign_id = compendium_entries.campaign_id and m.user_id = auth.uid() and m.role = 'gm'::campaign_role) or exists (select 1 from public.campaigns c where c.id = compendium_entries.campaign_id and c.owner_id = auth.uid()))) with check (campaign_id is not null and (exists (select 1 from public.campaign_members m where m.campaign_id = compendium_entries.campaign_id and m.user_id = auth.uid() and m.role = 'gm'::campaign_role) or exists (select 1 from public.campaigns c where c.id = compendium_entries.campaign_id and c.owner_id = auth.uid())));
